import cadquery as cq
YZ = [(-100.0, -83.0), (-100.0, 38.5), (-44.5, 94.0), (44.5, 94.0), (99.5, 39.0), (99.5, -83.5), (89.0, -94.0), (-89.0, -94.0)]
XZ = [(-88.5, -94), (78, -94), (88.9, -83.3), (88.9, 27.8), (70.2, 83.9), (55.6, 94.4), (22.2, 94.4), (22.2, 77), (29.8, 72.1), (36.6, 66.4), (42.6, 59.8), (44.5, 57.5), (44.5, -76.5), (-88.5, -77)]
XY = [(-88.5, -100.0), (-88.0, -61.0), (-83.5, -52.5), (-75.0, -46.5), (-59.5, -46.0), (-44.5, -58.0), (22.0, -58.0), (29.0, -51.0), (22.5, -44.5), (22.5, 44.5), (29.0, 51.0), (22.0, 58.0), (-44.5, 58.0), (-59.5, 46.0), (-75.0, 46.5), (-83.5, 52.5), (-88.0, 61.0), (-88.5, 99.5), (56.0, 99.5), (70.0, 89.5), (88.5, 34.5), (88.5, -34.5), (70.0, -89.5), (55.5, -100.0)]
a = cq.Workplane('YZ', origin=(-110, 0, 0)).polyline(YZ).close().extrude(220)
b = cq.Workplane('XZ', origin=(0, 110, 0)).polyline(XZ).close().extrude(220)
c = cq.Workplane('XY', origin=(0, 0, -110)).polyline(XY).close().extrude(220)
r = a.intersect(b).intersect(c)
r = r.cut(cq.Workplane('XY').box(22.4, 89, 20).translate((33.3, 0, -85.5)))      # 팔 사이 빈 곳
r = r.cut(cq.Workplane('XY').sphere(69.2).rotate((0, 0, 0), (0, 0, 1), 180).translate((-11.5, 0, 16.7)))   # 안쪽 접시 홈 · 구의 이음매(+x 자오선)가 접시 한가운데 오면 STL 이 안 닫혀 180° 돌림
